mapper.select:
SELECT a.id, a.scheme_descr AS name, a.add_date AS create_time, COALESCE(NULLIF(b.realname, ''), b.username, a.add_userid) AS username, a.scheme_colums, a.scheme_conditon, a.add_userid FROM visual_screen.vs_lib_index_scheme a LEFT JOIN visual_screen.sys_user b ON a.add_userid = b.id WHERE 1 = 1
AND a.scheme_descr LIKE concat(concat('%', #{params.name}), '%')
AND a.add_date >= #{params.startDate}
AND a.add_date <= concat(#{params.endDate}, ' 23:59:59')
ORDER BY a.add_date DESC NULLS LAST LIMIT #{params.rows,jdbcType=INTEGER} OFFSET #{params.page,jdbcType=INTEGER}
